type Store = { employees: Employee[]; evaluations: Evaluation[]; activities: Activity[]; config: Config; addEvaluation: (e: Omit<Evaluation, 'id'>) => void; updateEvaluation: (e: Evaluation) => void; deleteEvaluation: (id: string) => void; addEmployee: (e: Omit<Employee, 'id'>) => void; updateEmployee: (e: Employee) => void; toggleEmployee: (id: string) => void; deleteEmployee: (id: string) => void; addActivity: (action: string, detail: string) => void; setConfig: (c: Config) => void; restoreData: (data: Partial<Pick<Store, 'employees' | 'evaluations' | 'activities' | 'config'>>) => void };
const StoreContext = createContext<Store | null>(null);
function useStore() { const v = useContext(StoreContext); if (!v) throw new Error('Store unavailable'); return v; }
function score(e: Evaluation) { return Math.round(e.quality * .4 + e.fcr * .2 + e.adherence * .2 + e.csat / 5 * 100 * .2); }
function avg(list: Evaluation[]) { return list.length ? Math.round(list.reduce((a, e) => a + score(e), 0) / list.length) : 0; }
function initials(name: string) { return name.split(' ').slice(0, 2).map(x => x[0]).join(''); }
function downloadText(filename: string, content: string, type = 'application/json') { const blob = new Blob([content], { type }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url); }

function Button({ children, variant = 'primary', onClick, className = '', type = 'button', disabled = false }: { children: ReactNode; variant?: 'primary' | 'soft' | 'ghost' | 'danger'; onClick?: () => void; className?: string; type?: 'button' | 'submit'; disabled?: boolean }) {
  return <button type={type} disabled={disabled} onClick={onClick} className={`inline-flex items-center justify-center gap-2 rounded-2xl px-4 py-2.5 text-sm font-bold transition-transform duration-200 active:scale-[.97] disabled:cursor-not-allowed disabled:opacity-50 ${variant === 'primary' ? 'bg-[#c5a7ee] text-[#392844] clay-sm hover:-translate-y-0.5' : variant === 'soft' ? 'bg-[#f9d7e3] text-[#6e354d] clay-sm hover:-translate-y-0.5' : variant === 'danger' ? 'bg-[#f7d1cf] text-[#8d3f43]' : 'bg-transparent text-[#806a73] hover:bg-[#eee0d5]'} ${className}`} data-testid={`button-${typeof children === 'string' ? children.replace(/\s/g, '-') : 'action'}`}>{children}</button>;
}
function Avatar({ employee, size = 'md' }: { employee?: Employee; size?: 'sm' | 'md' | 'lg' }) {
  const name = employee?.name || 'فريق الجودة';
  return <div className={`flex shrink-0 items-center justify-center rounded-[35%] font-extrabold text-[#493746] ${size === 'lg' ? 'h-14 w-14 text-lg' : size === 'sm' ? 'h-8 w-8 text-[11px]' : 'h-10 w-10 text-sm'}`} style={{ background: employee?.avatarColor || '#d9c4f2' }} aria-label={name}>{initials(name)}</div>;
}
function Badge({ children, tone = 'mint' }: { children: ReactNode; tone?: 'mint' | 'pink' | 'peach' | 'lavender' }) { const c = { mint: 'bg-[#d7f0df] text-[#397258]', pink: 'bg-[#f9d8e3] text-[#94506a]', peach: 'bg-[#f8e4c9] text-[#956637]', lavender: 'bg-[#e7dcf8] text-[#654a88]' }[tone]; return <span className={`rounded-full px-2.5 py-1 text-xs font-bold ${c}`}>{children}</span>; }
function Field({ label, value, onChange, type = 'text', placeholder = '' }: { label: string; value: string | number; onChange: (v: string) => void; type?: string; placeholder?: string }) {
  return <label className="block text-sm font-bold text-[#66545b]"><span className="mb-1.5 block">{label}</span><input type={type} value={value} placeholder={placeholder} onChange={e => onChange(e.target.value)} className="w-full rounded-2xl border border-[#e6d7d2] bg-[#fffaf3] px-3.5 py-3 font-medium outline-none transition focus:border-[#bf9ce8] focus:ring-4 focus:ring-[#dccaf5]" /></label>;
}

