    <aside className={`fixed inset-y-0 right-0 z-40 flex w-[250px] flex-col border-l border-[#eadcd3] bg-[#fbf6ec]/95 p-4 backdrop-blur-xl transition-transform duration-300 lg:translate-x-0 ${mobileOpen ? 'translate-x-0' : 'translate-x-full'}`}>
      <div className="mb-8 flex items-center gap-3 px-2"><div className="flex h-11 w-11 rotate-[-8deg] items-center justify-center rounded-[32%] bg-[#c6a6ef] text-[#4c3564] clay-sm"><ShieldCheck size={24} /></div><div><div className="font-display text-xl font-extrabold leading-none text-[#5a3e52]">الجودة</div><div className="text-[10px] font-bold text-[#ad8a94]">نظام إدارة الجودة</div></div></div>
      <div className="mb-3 px-3 text-[11px] font-extrabold tracking-widest text-[#b79ea3]">مساحة العمل</div>
      <nav className="space-y-1.5">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setMobileOpen(false)} className={`flex items-center gap-3 rounded-2xl px-3.5 py-3 text-sm font-bold transition ${location === href ? href === '/' ? 'bg-[#c9ead8] text-[#35604d] clay-sm' : href === '/evaluations' ? 'bg-[#f2b8ca] text-[#713f55] clay-sm' : 'bg-[#d8c3f5] text-[#4e3c63] clay-sm' : 'text-[#806b73] hover:bg-[#f0e3d8]'}`} data-testid={`link-nav-${label}`}><Icon size={18} strokeWidth={2.2} /><span>{label}</span>{href === '/' && <span className="mr-auto h-2 w-2 rounded-full bg-[#e999b5]" />}</Link>)}</nav>
      <div className="mt-7 border-t border-[#eadcd3] pt-5"><div className="mb-3 px-3 text-[11px] font-extrabold tracking-widest text-[#b79ea3]">الإدارة</div><Link href="/settings" onClick={() => setMobileOpen(false)} className={`flex items-center gap-3 rounded-2xl px-3.5 py-3 text-sm font-bold ${location === '/settings' ? 'bg-[#d8c3f5] text-[#4e3c63]' : 'text-[#806b73] hover:bg-[#f0e3d8]'}`} data-testid="link-nav-settings"><Settings size={18} /><span>الإعدادات</span></Link></div>
      <div className="mt-auto rounded-[24px] bg-[#e7f4e1] p-4 clay-sm"><div className="mb-2 flex items-center gap-2 text-[#416c55]"><Sparkles size={17} /><span className="text-sm font-extrabold">نظام إدارة الجودة</span></div><p className="text-xs leading-5 text-[#62806b]">كل تغييراتك محفوظة محلياً ويمكنك تجربتها بأمان.</p></div>
      <div className="mt-4 flex items-center gap-3 rounded-2xl bg-[#f4e8df] p-3"><Avatar size="sm" /><div className="min-w-0 flex-1"><div className="truncate text-sm font-extrabold">مديرة الجودة</div><div className="text-[11px] text-[#a4888e]">وضع تجريبي</div></div><button aria-label="تسجيل الخروج" className="text-[#a8878f]" onClick={() => setMobileOpen(false)} data-testid="button-logout"><LogOut size={16} /></button></div>
    </aside>
    {mobileOpen && <button className="fixed inset-0 z-30 bg-[#3e2838]/20 lg:hidden" onClick={() => setMobileOpen(false)} aria-label="إغلاق القائمة" />}
