function Dashboard() {
  const { employees, evaluations } = useStore(); const [, setLocation] = useLocation();
  const active = employees.filter(e => e.active);
  const avgScore = avg(evaluations);
  const totalCalls = evaluations.reduce((a, e) => a + e.calls, 0);
  const ranking = active.map(e => ({ employee: e, score: avg(evaluations.filter(v => v.employeeId === e.id)) })).sort((a, b) => b.score - a.score);
  const weeks = [{ l: 'الأسبوع ١', v: 78 }, { l: 'الأسبوع ٢', v: 84 }, { l: 'الأسبوع ٣', v: 81 }, { l: 'الأسبوع ٤', v: 89 }, { l: 'هذا الأسبوع', v: avgScore }];
  return <div className="space-y-7">
    <section className="relative overflow-hidden rounded-[30px] bg-[#c9ead8] px-6 py-7 clay sm:px-9 sm:py-8"><div className="absolute -left-8 -top-10 h-36 w-36 rounded-full bg-[#e8f6e4]/70" /><div className="absolute bottom-[-55px] left-[32%] h-40 w-40 rounded-full bg-[#f1b9cb]/55" /><div className="relative flex flex-col justify-between gap-6 sm:flex-row sm:items-center"><div><div className="mb-2 flex items-center gap-2 text-sm font-bold text-[#4f8068]"><Sparkles size={16} /> الأربعاء، ١١ يونيو ٢٠٢٥</div><h2 className="font-display text-4xl font-extrabold leading-tight text-[#355b48] sm:text-5xl">أهلاً بكِ في<br /><span className="text-[#a85f7a]">نظام إدارة الجودة</span></h2><p className="mt-3 max-w-[420px] text-sm leading-6 text-[#567664]">كل مراجعة صغيرة تصنع تجربة أكبر. إليكِ نبض فريقك اليوم.</p></div><div className="flex items-end gap-2 sm:pl-8"><div className="flex -space-x-2 space-x-reverse">{active.slice(0, 4).map(e => <Avatar key={e.id} employee={e} size="lg" />)}</div><div className="mr-3 rounded-2xl bg-[#fff6ee]/75 px-4 py-3"><div className="text-2xl font-extrabold text-[#5e4055]">{active.length}</div><div className="text-xs font-bold text-[#638270]">عضوة نشطة</div></div></div></div></section>
    <div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-display text-2xl font-extrabold text-[#4e3843]">لمحة هذا الشهر</h3><p className="mt-1 text-sm text-[#9b8087]">أداء فريق خدمات ما بعد البيع · يونيو ٢٠٢٥</p></div><div className="flex gap-2"><Button variant="soft" onClick={() => alert('الفترة الحالية: يونيو ٢٠٢٥')}><Filter size={16} /> هذا الشهر</Button><Button onClick={() => setLocation('/evaluations')}><Plus size={17} /> تقييم جديد</Button></div></div>
    <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      <MetricCard icon={<ShieldCheck />} label="Quality" value={`${avgScore}%`} change="+4.8%" note="مقابل الشهر السابق" tone="lavender" />
      <MetricCard icon={<Headphones />} label="Total Calls" value={totalCalls.toLocaleString('ar-SA')} change="+12.6%" note="مكالمة تمت مراجعتها" tone="pink" />
      <MetricCard icon={<Target />} label="FCR" value="88.4%" change="+2.1%" note="من أول تواصل" tone="mint" />
      <MetricCard icon={<Star />} label="CSAT" value="4.6/5" change="+0.3" note="رضا العملاء" tone="peach" />
    </section>
    <section className="grid gap-5 xl:grid-cols-[1.35fr_.9fr]">
      <div className="rounded-[26px] bg-[#fffaf3] p-5 clay sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-display text-xl font-extrabold">مسار الجودة</h3><p className="text-xs text-[#a58c91]">متوسط الدرجة المركبة خلال الأسابيع</p></div><Badge tone="mint">في تحسّن</Badge></div><div className="flex h-[210px] items-end gap-3 border-b border-[#eadfd5] px-2 pb-0 sm:gap-6">{weeks.map((w, i) => <div key={w.l} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><span className="text-xs font-extrabold text-[#836b74]">{w.v}%</span><div className={`w-full max-w-[54px] rounded-t-[16px] ${i === 4 ? 'bg-[#e99bb7]' : 'bg-[#c9b0ee]'}`} style={{ height: `${w.v * 1.75}px` }} /><span className="mb-[-27px] whitespace-nowrap text-[10px] font-bold text-[#a58c91]">{w.l}</span></div>)}</div><div className="mt-10 flex items-center gap-2 text-xs font-bold text-[#8d747c]"><TrendingUp size={15} className="text-[#66a77d]" /> تحسّن ملحوظ في الالتزام منذ بداية الشهر</div></div>
      <div className="rounded-[26px] bg-[#d9f0de] p-5 clay sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-display text-xl font-extrabold text-[#385a48]">تنبيهات لطيفة</h3><p className="text-xs text-[#66816f]">أشياء تستحق نظرة منك</p></div><Bell size={21} className="text-[#70a583]" /></div><div className="space-y-3"><AlertRow tone="peach" title="تقييمان يحتاجان مراجعة" detail="مضى عليهما أكثر من ٧ أيام" /><AlertRow tone="pink" title="جود تحتاج جلسة متابعة" detail="انخفاض ٨٪ في FCR هذا الأسبوع" /><AlertRow tone="lavender" title="التقرير الشهري جاهز" detail="يمكنك مراجعته وتصديره الآن" /></div><Button variant="ghost" onClick={() => setLocation('/activity')} className="mt-3 w-full text-[#4f725c]">عرض كل التنبيهات <ChevronLeft size={15} /></Button></div>
    </section>
    <section className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]">
      <div className="rounded-[26px] bg-[#fffaf3] p-5 clay sm:p-6"><div className="mb-5 flex items-center justify-between"><h3 className="font-display text-xl font-extrabold">ترتيب الفريق</h3><Link href="/employee-report" className="text-xs font-bold text-[#a26a86]" data-testid="link-ranking-report">التقرير الكامل <ChevronLeft size={14} className="inline" /></Link></div><div className="space-y-3">{ranking.slice(0, 4).map((r, i) => <Link href={`/employee-report?employee=${r.employee.id}`} key={r.employee.id} className="flex items-center gap-3 rounded-2xl p-2 transition hover:bg-[#f7ede4]" data-testid={`link-employee-${r.employee.id}`}><span className="w-5 text-center font-display text-lg font-extrabold text-[#b89fa5]">{i + 1}</span><Avatar employee={r.employee} size="sm" /><div className="min-w-0 flex-1"><div className="truncate text-sm font-extrabold">{r.employee.name}</div><div className="text-[11px] text-[#a58990]">{r.employee.role}</div></div><div className="text-left"><div className="font-display text-lg font-extrabold text-[#614b58]">{r.score}%</div><div className="text-[10px] text-[#6aa278]">ممتاز</div></div></Link>)}</div></div>
      <div className="rounded-[26px] bg-[#f8d8e4] p-5 clay sm:p-6"><div className="mb-5 flex items-center gap-3"><div className="rounded-2xl bg-[#fff1e9]/70 p-3 text-[#9e5d75]"><BookOpen size={21} /></div><div><h3 className="font-display text-xl font-extrabold text-[#673e51]">آخر ما حدث</h3><p className="text-xs text-[#986e7e]">نشاط فريق الجودة</p></div></div><div className="space-y-4">{activitySeed.slice(0, 3).map((a, i) => <div className="flex gap-3" key={a.id}><div className="mt-1 h-2.5 w-2.5 rounded-full bg-[#e98aaa]" /><div><p className="text-sm font-bold text-[#6d4757]">{a.user} <span className="font-normal">{a.action}</span></p><p className="mt-0.5 text-xs text-[#9a6f7f]">{a.detail} · {a.timestamp}</p></div></div>)}</div><Link href="/activity" className="mt-5 inline-flex items-center gap-1 text-xs font-bold text-[#8a536a]" data-testid="link-view-activity">فتح سجل النشاط <ChevronLeft size={14} /></Link></div>
    </section>
  </div>;
}
function MetricCard({ icon, label, value, change, note, tone }: { icon: ReactNode; label: string; value: string; change: string; note: string; tone: 'lavender' | 'pink' | 'mint' | 'peach' }) {
  const bg = { lavender: 'bg-[#e5dafa]', pink: 'bg-[#f9d6e2]', mint: 'bg-[#d8efdd]', peach: 'bg-[#f7e3c6]' }[tone];
  return <div className={`rounded-[24px] ${bg} p-5 clay-sm`}><div className="mb-4 flex items-center justify-between"><div className="rounded-2xl bg-[#fffaf3]/70 p-2.5 text-[#735d78]">{icon}</div><Badge tone={tone === 'mint' ? 'mint' : tone === 'pink' ? 'pink' : tone === 'peach' ? 'peach' : 'lavender'}>{change}</Badge></div><div className="font-display text-3xl font-extrabold text-[#4d3b45]">{value}</div><div className="mt-1 text-sm font-extrabold text-[#66505a]">{label}</div><div className="mt-1 text-xs text-[#9a8188]">{note}</div></div>;
}
function AlertRow({ tone, title, detail }: { tone: 'peach' | 'pink' | 'lavender'; title: string; detail: string }) { return <div className="flex items-center gap-3 rounded-2xl bg-[#fffaf3]/70 p-3"><div className={`h-3 w-3 rounded-full ${tone === 'peach' ? 'bg-[#f0b36f]' : tone === 'pink' ? 'bg-[#e992b3]' : 'bg-[#b296df]'}`} /><div className="min-w-0 flex-1"><div className="text-sm font-extrabold text-[#45614f]">{title}</div><div className="text-xs text-[#71907a]">{detail}</div></div><ChevronLeft size={16} className="text-[#7ca188]" /></div>; }

function PageHeader({ title, description, action }: { title: string; description: string; action?: ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h2 className="font-display text-3xl font-extrabold text-[#4e3843]">{title}</h2><p className="mt-1 text-sm text-[#9b8087]">{description}</p></div>{action}</div>; }
function EvaluationForm({ initial, onSave, onClose }: { initial?: Evaluation; onSave: (e: Omit<Evaluation, 'id'> | Evaluation) => void; onClose: () => void }) {
  const { employees } = useStore(); const [form, setForm] = useState({ date: initial?.date || '2025-06-11', employeeId: initial?.employeeId || employees[0].id, calls: String(initial?.calls || 120), quality: String(initial?.quality || 90), fcr: String(initial?.fcr || 85), adherence: String(initial?.adherence || 94), csat: String(initial?.csat || 4.5), complaints: String(initial?.complaints || 1), note: initial?.note || '' });
  const set = (k: string, v: string) => setForm(f => ({ ...f, [k]: v }));
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#43303e]/25 p-4 backdrop-blur-sm"><form onSubmit={e => { e.preventDefault(); const data = { date: form.date, employeeId: form.employeeId, calls: Number(form.calls), quality: Number(form.quality), fcr: Number(form.fcr), adherence: Number(form.adherence), csat: Number(form.csat), complaints: Number(form.complaints), note: form.note }; onSave(initial ? { ...data, id: initial.id } : data); }} className="max-h-[92vh] w-full max-w-2xl overflow-auto rounded-[30px] bg-[#fffaf3] p-5 clay sm:p-7"><div className="mb-6 flex items-start justify-between"><div><h3 className="font-display text-2xl font-extrabold">{initial ? 'تعديل التقييم' : 'تقييم جديد'}</h3><p className="mt-1 text-xs text-[#a58b91]">أضيفي تفاصيل المكالمة بدقة ودفء</p></div><button type="button" onClick={onClose} className="rounded-xl p-2 hover:bg-[#f2e7de]" aria-label="إغلاق" data-testid="button-close-form"><X size={20} /></button></div><div className="grid gap-4 sm:grid-cols-2"><Field label="تاريخ التقييم" value={form.date} onChange={v => set('date', v)} type="date" /><label className="block text-sm font-bold text-[#66545b]"><span className="mb-1.5 block">الموظف</span><select value={form.employeeId} onChange={e => set('employeeId', e.target.value)} className="w-full rounded-2xl border border-[#e6d7d2] bg-[#fffaf3] px-3.5 py-3 outline-none" data-testid="select-evaluation-employee">{employees.filter(x => x.active).map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select></label><Field label="عدد المكالمات" value={form.calls} onChange={v => set('calls', v)} type="number" /><Field label="Quality %" value={form.quality} onChange={v => set('quality', v)} type="number" /><Field label="FCR %" value={form.fcr} onChange={v => set('fcr', v)} type="number" /><Field label="Adherence %" value={form.adherence} onChange={v => set('adherence', v)} type="number" /><Field label="CSAT / 5" value={form.csat} onChange={v => set('csat', v)} type="number" /><Field label="الشكاوى" value={form.complaints} onChange={v => set('complaints', v)} type="number" /></div><label className="mt-4 block text-sm font-bold text-[#66545b]"><span className="mb-1.5 block">ملاحظة المديرة</span><textarea value={form.note} onChange={e => set('note', e.target.value)} rows={3} placeholder="ما الذي لفت انتباهك؟" className="w-full resize-none rounded-2xl border border-[#e6d7d2] bg-[#fffaf3] px-3.5 py-3 outline-none focus:border-[#bf9ce8]" /></label><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={onClose}>إلغاء</Button><Button type="submit"><Check size={17} /> حفظ التقييم</Button></div></form></div>;
}
function Evaluations() {
  const { evaluations, employees, addEvaluation, updateEvaluation, deleteEvaluation, addActivity } = useStore(); const [editing, setEditing] = useState<Evaluation | undefined>(); const [open, setOpen] = useState(false); const [query, setQuery] = useState('');
  const rows = evaluations.filter(e => employees.find(x => x.id === e.employeeId)?.name.includes(query));
  return <div><PageHeader title="التقييمات" description="راجعي جودة التفاعلات، أضيفي ملاحظاتك، واحتفظي بسياق كل مكالمة." action={<Button onClick={() => { setEditing(undefined); setOpen(true); }}><Plus size={17} /> تقييم جديد</Button>} /><div className="mb-5 flex flex-wrap items-center gap-3"><div className="relative min-w-[230px] flex-1 sm:max-w-sm"><Search size={17} className="absolute right-3 top-3.5 text-[#a78d94]" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="ابحثي عن موظف..." className="w-full rounded-2xl border border-[#eadbd3] bg-[#fffaf3] py-3 pr-10 pl-4 text-sm outline-none focus:border-[#c5a7ee]" data-testid="input-search-evaluations" /></div><Button variant="soft"><Filter size={16} /> كل التقييمات <ChevronLeft size={15} /></Button></div><div className="overflow-hidden rounded-[26px] bg-[#fffaf3] clay"><div className="hidden grid-cols-[1.2fr_1fr_repeat(4,.6fr)_auto] gap-4 border-b border-[#eee0d7] px-6 py-4 text-xs font-extrabold text-[#aa8e95] lg:grid"><span>الموظف / التاريخ</span><span>الدرجة المركبة</span><span>Quality</span><span>FCR</span><span>CSAT</span><span>الشكاوى</span><span /></div>{rows.map(e => { const emp = employees.find(x => x.id === e.employeeId)!; const s = score(e); return <div key={e.id} className="grid gap-3 border-b border-[#f0e4dc] px-4 py-4 last:border-0 sm:px-6 lg:grid-cols-[1.2fr_1fr_repeat(4,.6fr)_auto] lg:items-center"><div className="flex items-center gap-3"><Avatar employee={emp} size="sm" /><div><div className="text-sm font-extrabold">{emp.name}</div><div className="text-xs text-[#a88d94]">{e.date}</div></div></div><div><span className="font-display text-xl font-extrabold text-[#614b58]">{s}%</span><div className="mt-1 h-1.5 w-20 rounded-full bg-[#eee3dd]"><div className={`h-full rounded-full ${s >= 90 ? 'bg-[#7fc392]' : s >= 80 ? 'bg-[#eeb875]' : 'bg-[#e99caf]'}`} style={{ width: `${s}%` }} /></div></div><div className="text-xs font-bold lg:text-sm">{e.quality}%</div><div className="text-xs font-bold lg:text-sm">{e.fcr}%</div><div className="text-xs font-bold lg:text-sm">{e.csat}</div><div className="text-xs font-bold">{e.complaints}</div><div className="flex gap-1"><button onClick={() => { setEditing(e); setOpen(true); }} className="rounded-xl p-2 text-[#977f88] hover:bg-[#eee2db]" aria-label="تعديل" data-testid={`button-edit-evaluation-${e.id}`}><Pencil size={15} /></button><button onClick={() => { if (confirm('حذف هذا التقييم؟')) { deleteEvaluation(e.id); addActivity('حذفت تقييماً', `${emp.name} · ${e.date}`); } }} className="rounded-xl p-2 text-[#c47b83] hover:bg-[#f8dede]" aria-label="حذف" data-testid={`button-delete-evaluation-${e.id}`}><Trash2 size={15} /></button></div><div className="rounded-xl bg-[#faf1e7] p-2 text-xs leading-5 text-[#896f76] lg:col-span-full">ملاحظة: {e.note || 'لا توجد ملاحظة'}</div></div>; })}</div>{!rows.length && <Empty title="لا توجد تقييمات" detail="جرّبي كلمة بحث مختلفة أو أضيفي تقييماً جديداً." action={<Button onClick={() => setOpen(true)}><Plus size={16} /> إضافة تقييم</Button>} />}{open && <EvaluationForm initial={editing} onClose={() => setOpen(false)} onSave={data => { if ('id' in data) { updateEvaluation(data); addActivity('عدّلت تقييماً', `${employees.find(x => x.id === data.employeeId)?.name}`); } else { addEvaluation(data); addActivity('أضافت تقييماً', employees.find(x => x.id === data.employeeId)?.name || ''); } setOpen(false); }} />}</div>;
}
function BulkEntry() {
  const { employees, evaluations, addEvaluation, updateEvaluation, addActivity } = useStore(); const [date, setDate] = useState('2025-06-11'); const active = employees.filter(e => e.active); const [values, setValues] = useState<Record<string, string>>({});
  const get = (id: string) => { const x = evaluations.find(e => e.employeeId === id && e.date === date); return values[id] ?? (x ? String(x.quality) : '90'); };
  return <div><PageHeader title="إدخال جماعي" description="أنشئي قياسات يوم واحد للفريق في دقائق، مع الحفاظ على مرونة التعديل." action={<Button onClick={() => { active.forEach(emp => { const old = evaluations.find(e => e.employeeId === emp.id && e.date === date); const data = { date, employeeId: emp.id, calls: 120, quality: Number(get(emp.id)), fcr: 86, adherence: 94, csat: 4.5, complaints: 1, note: 'إدخال جماعي — يحتاج مراجعة التفاصيل.' }; old ? updateEvaluation({ ...old, ...data }) : addEvaluation(data); }); addActivity('حفظ إدخالات جماعية', `${active.length} موظفات · ${date}`); alert('تم حفظ إدخالات الفريق بنجاح'); }}><Check size={17} /> حفظ الكل</Button>} /><div className="mb-5 flex max-w-sm items-end gap-3"><Field label="تاريخ التقييم" value={date} onChange={setDate} type="date" /><Button variant="soft" onClick={() => alert(`تم تجهيز صفوف ${date}`)}><Filter size={16} /> عرض</Button></div><div className="rounded-[26px] bg-[#fffaf3] p-4 clay sm:p-6"><div className="mb-5 flex items-center gap-3 rounded-2xl bg-[#e9ddf8] p-4 text-[#5d4773]"><ClipboardCheck size={20} /><div><div className="font-extrabold">تقييمات {date}</div><div className="text-xs opacity-70">أدخلي الدرجة الأساسية، ثم عودي لاحقاً للتفاصيل.</div></div></div><div className="space-y-3">{active.map((emp, i) => <div key={emp.id} className="grid items-center gap-3 rounded-2xl bg-[#fcf6ed] p-3 sm:grid-cols-[1fr_130px_1.2fr]"><div className="flex items-center gap-3"><div className="font-display text-lg font-extrabold text-[#b39ba0]">{i + 1}</div><Avatar employee={emp} size="sm" /><div><div className="text-sm font-extrabold">{emp.name}</div><div className="text-xs text-[#a58a91]">{emp.role}</div></div></div><div><label className="text-xs font-bold text-[#92787f]">Quality %</label><input type="number" value={get(emp.id)} onChange={e => setValues(v => ({ ...v, [emp.id]: e.target.value }))} className="mt-1 w-full rounded-xl border border-[#e5d6cf] bg-[#fffaf3] px-3 py-2 font-bold outline-none focus:border-[#c5a7ee]" data-testid={`input-bulk-quality-${emp.id}`} /></div><div className="hidden text-xs text-[#9c838a] sm:block">{evaluations.find(e => e.employeeId === emp.id && e.date === date) ? 'تم إدخاله مسبقاً — سيُحدّث عند الحفظ' : 'لم يتم إدخال تقييم لهذا اليوم'}</div></div>)}</div></div></div>;
}
function Employees() {
  const { employees, evaluations, addEmployee, updateEmployee, toggleEmployee, deleteEmployee, addActivity } = useStore(); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Employee>(); const [form, setForm] = useState({ name: '', role: 'أخصائية خدمة عملاء', avatarColor: '#c3a5ef' });
  const start = (e?: Employee) => { setEditing(e); setForm(e ? { name: e.name, role: e.role, avatarColor: e.avatarColor } : { name: '', role: 'أخصائية خدمة عملاء', avatarColor: '#c3a5ef' }); setOpen(true); };
  return <div><PageHeader title="الموظفون" description="دليل فريقك في لمحة. تابعي الحالة، المسؤوليات، واتركي مساحة للنمو." action={<Button onClick={() => start()}><Plus size={17} /> إضافة موظف</Button>} /><div className="mb-5 flex gap-2"><Badge tone="mint">{employees.filter(e => e.active).length} نشطة</Badge><Badge tone="peach">{employees.filter(e => !e.active).length} متوقفة مؤقتاً</Badge></div><div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{employees.map(e => { const hasEvaluations = evaluations.some(v => v.employeeId === e.id); return <div key={e.id} className={`rounded-[26px] bg-[#fffaf3] p-5 clay transition hover:-translate-y-1 ${!e.active ? 'opacity-70' : ''}`}><div className="mb-5 flex items-start justify-between"><Avatar employee={e} size="lg" /><div className="flex gap-1"><button onClick={() => start(e)} className="rounded-xl p-2 text-[#967e86] hover:bg-[#f1e5db]" aria-label="تعديل الموظف" data-testid={`button-edit-employee-${e.id}`}><Pencil size={16} /></button><button onClick={() => { toggleEmployee(e.id); addActivity(e.active ? 'أوقفت موظفاً مؤقتاً' : 'فعّلت موظفاً', e.name); }} className="rounded-xl p-2 text-[#967e86] hover:bg-[#f1e5db]" aria-label="تبديل الحالة" data-testid={`button-toggle-employee-${e.id}`}><Zap size={16} /></button><button disabled={hasEvaluations} onClick={() => { if (confirm(`حذف ${e.name} نهائياً؟`)) { deleteEmployee(e.id); addActivity('حذفت موظفاً', e.name); } }} className="rounded-xl p-2 text-[#c47b83] hover:bg-[#f8dede] disabled:cursor-not-allowed disabled:opacity-30" aria-label={hasEvaluations ? 'لا يمكن حذف موظف لديه تقييمات' : 'حذف الموظف'} data-testid={`button-delete-employee-${e.id}`}><Trash2 size={16} /></button></div></div><div className="text-lg font-extrabold">{e.name}</div><div className="mt-1 text-sm text-[#9b8087]">{e.role}</div><div className="mt-5 flex items-center justify-between border-t border-[#f0e2d9] pt-4"><Badge tone={e.active ? 'mint' : 'peach'}>{e.active ? 'نشطة' : 'متوقفة مؤقتاً'}</Badge><Link href={`/employee-report?employee=${e.id}`} className="text-xs font-bold text-[#a36982]" data-testid={`link-report-employee-${e.id}`}>عرض التقرير <ChevronLeft size={14} className="inline" /></Link></div></div>; })}</div>{open && <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#43303e]/25 p-4 backdrop-blur-sm"><form onSubmit={e => { e.preventDefault(); const data = { ...form, active: editing?.active ?? true }; editing ? updateEmployee({ ...data, id: editing.id }) : addEmployee(data); addActivity(editing ? 'عدّلت بيانات موظف' : 'أضافت موظفاً', form.name); setOpen(false); }} className="w-full max-w-md rounded-[30px] bg-[#fffaf3] p-6 clay"><div className="mb-5 flex justify-between"><h3 className="font-display text-2xl font-extrabold">{editing ? 'تعديل موظف' : 'موظف جديد'}</h3><button type="button" onClick={() => setOpen(false)} aria-label="إغلاق"><X size={19} /></button></div><div className="space-y-4"><Field label="الاسم" value={form.name} onChange={v => setForm({ ...form, name: v })} placeholder="مثال: مها السالم" /><Field label="المسمى الوظيفي" value={form.role} onChange={v => setForm({ ...form, role: v })} /><label className="block text-sm font-bold text-[#66545b]">لون الصورة<div className="mt-2 flex gap-2">{['#c3a5ef', '#f59ab6', '#9fd9b6', '#f3c77b', '#9fc5df'].map(c => <button type="button" key={c} onClick={() => setForm({ ...form, avatarColor: c })} className={`h-9 w-9 rounded-xl ${form.avatarColor === c ? 'ring-2 ring-[#6d5577] ring-offset-2' : ''}`} style={{ background: c }} aria-label={`اختيار اللون ${c}`} />)}</div></label></div><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={() => setOpen(false)}>إلغاء</Button><Button type="submit"><Check size={16} /> حفظ</Button></div></form></div>}</div>;
}
function EmployeeReport() {
  const { employees, evaluations } = useStore(); const params = new URLSearchParams(window.location.search); const selected = employees.find(e => e.id === params.get('employee')) || employees[0]; const own = evaluations.filter(e => e.employeeId === selected.id); const team = avg(evaluations); const ownScore = avg(own);
  return <div><PageHeader title="تقرير الموظف" description="صورة واضحة تساعدك على تحويل الأرقام إلى محادثة تدريبية جيدة." action={<Button variant="soft" onClick={() => window.print()}><Printer size={16} /> طباعة التقرير</Button>} /><div className="mb-6 flex flex-wrap gap-2">{employees.filter(e => e.active).map(e => <Link key={e.id} href={`/employee-report?employee=${e.id}`} className={`flex items-center gap-2 rounded-2xl px-3 py-2 text-xs font-bold ${e.id === selected.id ? 'bg-[#d8c3f5] text-[#4f3c61] clay-sm' : 'bg-[#f1e5dc] text-[#876f77]'}`} data-testid={`link-select-employee-${e.id}`}><Avatar employee={e} size="sm" />{e.name}</Link>)}</div><section className="grid gap-5 xl:grid-cols-[.75fr_1.25fr]"><div className="rounded-[28px] bg-[#d9c5f4] p-6 clay"><div className="flex items-center gap-4"><Avatar employee={selected} size="lg" /><div><h3 className="font-display text-2xl font-extrabold text-[#4f3b5c]">{selected.name}</h3><p className="text-sm text-[#806988]">{selected.role}</p></div></div><div className="my-7 flex items-end gap-2"><span className="font-display text-6xl font-extrabold text-[#503a5d]">{ownScore}</span><span className="mb-2 text-xl font-bold text-[#775c7f]">%</span></div><div className="text-sm font-bold text-[#71587a]">الدرجة المركبة</div><div className="mt-4 flex items-center gap-2 text-xs font-bold text-[#567761]"><TrendingUp size={15} /> أعلى من متوسط الفريق بـ {Math.max(0, ownScore - team)} نقاط</div></div><div className="rounded-[28px] bg-[#fffaf3] p-6 clay"><div className="mb-6 flex items-center justify-between"><h3 className="font-display text-xl font-extrabold">مقارنة الأداء</h3><Badge tone="mint">آخر ٣٠ يوماً</Badge></div><div className="space-y-6">{[['Quality', own.length ? Math.round(own.reduce((a, e) => a + e.quality, 0) / own.length) : 0, 90], ['FCR', own.length ? Math.round(own.reduce((a, e) => a + e.fcr, 0) / own.length) : 0, 85], ['Adherence', own.length ? Math.round(own.reduce((a, e) => a + e.adherence, 0) / own.length) : 0, 94], ['CSAT', own.length ? Math.round(own.reduce((a, e) => a + e.csat, 0) / own.length * 20) : 0, 90]].map(([label, value, target]) => <div key={label as string}><div className="mb-2 flex justify-between text-sm font-bold"><span>{label}</span><span className="text-[#8f717b]">{value}% <span className="text-xs font-normal">/ هدف {target}%</span></span></div><div className="h-3 rounded-full bg-[#eee2d9]"><div className="h-full rounded-full bg-[#c5a7ee]" style={{ width: `${Math.min(100, Number(value))}%` }} /></div></div>)}</div></div></section><section className="mt-5 rounded-[28px] bg-[#f8d8e4] p-6 clay"><div className="mb-5 flex items-center gap-3"><div className="rounded-2xl bg-[#fff4ee]/70 p-3 text-[#a65c78]"><BookOpen size={20} /></div><div><h3 className="font-display text-xl font-extrabold text-[#643e51]">ملاحظات التدريب</h3><p className="text-xs text-[#986c7b]">مساحة للمحادثات التي تصنع فرقاً</p></div></div><div className="grid gap-3 sm:grid-cols-2">{own.slice(0, 4).map(e => <div key={e.id} className="rounded-2xl bg-[#fff7ef]/70 p-4"><div className="mb-2 text-xs font-bold text-[#a2697f]">{e.date}</div><p className="text-sm font-bold leading-6 text-[#704c5d]">“{e.note}”</p></div>)}{!own.length && <Empty title="لا توجد ملاحظات بعد" detail="ابدئي بتقييم الموظف لإضافة سياق تدريبي." />}</div></section></div>;
}
function MonthlyReport() {
  const { evaluations, employees } = useStore(); const scoreNow = avg(evaluations); const goals = [{ label: 'Quality', value: scoreNow, target: 90, color: '#b69be5' }, { label: 'FCR', value: 88, target: 85, color: '#e99ab6' }, { label: 'Adherence', value: 93, target: 94, color: '#83c69a' }, { label: 'CSAT', value: 92, target: 90, color: '#f1bc77' }];
  return <div><PageHeader title="التقرير الشهري الرسمي" description="نسخة رسمية قابلة للمشاركة عن نبض جودة الخدمة في يونيو ٢٠٢٥." action={<div className="flex gap-2"><Button variant="soft" onClick={() => window.print()}><Printer size={16} /> طباعة / حفظ PDF</Button><Button onClick={() => window.print()}><Download size={16} /> تصدير PDF</Button></div>} /><div className="mx-auto max-w-[1050px] rounded-[30px] bg-[#fffaf3] p-5 clay sm:p-10"><div className="flex flex-col justify-between gap-5 border-b border-[#eadfd5] pb-7 sm:flex-row sm:items-start"><div><div className="mb-3 flex items-center gap-2 text-[#9c6d84]"><ShieldCheck size={23} /><span className="font-display text-xl font-extrabold">نظام إدارة الجودة</span></div><h2 className="font-display text-4xl font-extrabold text-[#4d3744]">التقرير الشهري الرسمي</h2><p className="mt-2 text-sm text-[#9b8087]">يونيو ٢٠٢٥ · خدمات ما بعد البيع</p></div><div className="rounded-2xl bg-[#e8dcf8] px-5 py-4 text-center"><div className="font-display text-4xl font-extrabold text-[#5d4671]">{scoreNow}%</div><div className="text-xs font-bold text-[#7d6690]">النتيجة النهائية</div></div></div><div className="my-8 grid gap-4 sm:grid-cols-4">{goals.map(g => <div className="rounded-2xl bg-[#faf1e8] p-4" key={g.label}><div className="text-sm font-extrabold">{g.label}</div><div className="mt-2 font-display text-3xl font-extrabold" style={{ color: g.color }}>{g.value}%</div><div className="mt-1 text-xs text-[#9d838a]">الهدف {g.target}%</div><div className="mt-3 h-2 rounded-full bg-[#eaded5]"><div className="h-full rounded-full" style={{ width: `${Math.min(100, g.value)}%`, background: g.color }} /></div></div>)}</div><div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div><h3 className="mb-4 font-display text-xl font-extrabold">ملخص تنفيذي</h3><p className="rounded-2xl bg-[#d9f0de] p-5 text-sm font-bold leading-7 text-[#45614f]">حافظ الفريق على مسار إيجابي خلال هذا الشهر، مع تحسن ملحوظ في جودة التوثيق ورضا العملاء. نوصي بالاستمرار في جلسات الاستماع الأسبوعية والتركيز على رفع FCR في فريق المساء.</p></div><div><h3 className="mb-4 font-display text-xl font-extrabold">القدرة التشغيلية</h3><div className="space-y-3 rounded-2xl bg-[#f8d8e4] p-5"><div className="flex justify-between text-sm"><span>المكالمات المراجعة</span><b>{evaluations.reduce((a, e) => a + e.calls, 0).toLocaleString('ar-SA')}</b></div><div className="flex justify-between text-sm"><span>الفريق النشط</span><b>{employees.filter(e => e.active).length} موظفات</b></div><div className="flex justify-between text-sm"><span>الشكاوى المرصودة</span><b>{evaluations.reduce((a, e) => a + e.complaints, 0)}</b></div></div></div></div><div className="mt-8 border-t border-[#eadfd5] pt-6 text-center text-xs font-bold text-[#ac9298]">أُعدّ بواسطة نظام إدارة الجودة · وضع العرض التجريبي · ١١ يونيو ٢٠٢٥</div></div></div>;
}
function Activity() { const { activities } = useStore(); return <div><PageHeader title="سجل التغييرات" description="كل تغيير مهم، في مكان واضح يمكن الرجوع إليه." action={<Button variant="soft" onClick={() => downloadText(`quality-activity-${new Date().toISOString().slice(0, 10)}.json`, JSON.stringify(activities, null, 2))}><Download size={16} /> تصدير السجل</Button>} /><div className="rounded-[26px] bg-[#fffaf3] p-5 clay sm:p-7"><div className="mb-6 flex items-center gap-3"><div className="rounded-2xl bg-[#d9f0de] p-3 text-[#4c8a68]"><Zap size={19} /></div><div><h3 className="font-display text-xl font-extrabold">الحركات الأخيرة</h3><p className="text-xs text-[#a58c91]">مسجل تلقائياً من نظام إدارة الجودة</p></div></div><div className="relative mr-2 border-r-2 border-[#e9dcd5] pr-7">{activities.map((a, i) => <div key={a.id} className="relative mb-7 last:mb-0"><div className="absolute -right-[36px] top-1 h-4 w-4 rounded-full border-4 border-[#fffaf3] bg-[#c5a7ee]" /><div className="flex flex-col justify-between gap-2 sm:flex-row"><div><div className="text-sm font-extrabold">{a.user} <span className="font-normal text-[#816d74]">{a.action}</span></div><div className="mt-1 text-sm text-[#8d747c]">{a.detail}</div></div><div className="text-xs font-bold text-[#b0989e]">{a.timestamp}</div></div></div>)}</div></div></div>; }
function SettingsPage() { const { employees, evaluations, activities, config, setConfig, restoreData, addActivity } = useStore(); const [local, setLocal] = useState(config); const [saved, setSaved] = useState(false); const update = (group: 'weights' | 'targets' | 'thresholds', key: string, value: string) => setLocal(x => ({ ...x, [group]: { ...x[group], [key]: Number(value) } })); const exportBackup = () => { downloadText(`quality-backup-${new Date().toISOString().slice(0, 10)}.json`, JSON.stringify({ employees, evaluations, activities, config }, null, 2)); addActivity('صدّرت نسخة احتياطية', 'بيانات النظام كاملة'); }; const importBackup = async (file: File) => { try { const data = JSON.parse(await file.text()); if (!Array.isArray(data.employees) || !Array.isArray(data.evaluations) || !data.config) throw new Error('invalid'); restoreData(data); setLocal(data.config); addActivity('استوردت نسخة احتياطية', 'تم استعادة بيانات النظام'); alert('تم استيراد النسخة الاحتياطية بنجاح'); } catch { alert('ملف النسخة الاحتياطية غير صالح'); } }; return <div><PageHeader title="الإعدادات" description="اضبطي ما تعنيه الجودة لفريقك، واحتفظي بنسخة من إعداداتك." action={<Button onClick={() => { setConfig(local); addActivity('حدّثت الإعدادات', 'الأوزان والأهداف'); setSaved(true); setTimeout(() => setSaved(false), 2200); }}><Check size={16} /> {saved ? 'تم الحفظ' : 'حفظ التغييرات'}</Button>} /><div className="grid gap-5 lg:grid-cols-2"><SettingsCard title="أوزان المؤشرات" description="كيف تُحسب الدرجة المركبة؟" icon={<BarChart3 size={19} />}>{Object.entries(local.weights).map(([k, v]) => <SettingSlider key={k} label={k === 'quality' ? 'Quality' : k === 'fcr' ? 'FCR' : k === 'adherence' ? 'Adherence' : 'CSAT'} value={v} onChange={n => update('weights', k, String(n))} suffix="%" />)}</SettingsCard><SettingsCard title="الأهداف الشهرية" description="المستوى الذي يحتفل به فريقك" icon={<Target size={19} />}>{Object.entries(local.targets).map(([k, v]) => <SettingSlider key={k} label={k === 'quality' ? 'Quality' : k === 'fcr' ? 'FCR' : k === 'adherence' ? 'Adherence' : 'CSAT'} value={v} onChange={n => update('targets', k, String(n))} suffix={k === 'csat' ? '/ 5' : '%'} />)}</SettingsCard><SettingsCard title="حدود التقييم" description="متى نحتاج إلى احتفال أو جلسة دعم؟" icon={<ShieldCheck size={19} />}><SettingSlider label="ممتاز من" value={local.thresholds.excellent} onChange={n => update('thresholds', 'excellent', String(n))} suffix="%" /><SettingSlider label="يحتاج دعماً تحت" value={local.thresholds.needs} onChange={n => update('thresholds', 'needs', String(n))} suffix="%" /></SettingsCard><SettingsCard title="النسخ والاستيراد" description="استعيدي بيانات النظام أو احفظيها في ملف مستقل" icon={<Upload size={19} />}><div className="grid gap-3 sm:grid-cols-2"><Button variant="soft" onClick={exportBackup}><Download size={16} /> تصدير نسخة</Button><label className="inline-flex cursor-pointer items-center justify-center gap-2 rounded-2xl px-4 py-2.5 text-sm font-bold text-[#806a73] hover:bg-[#eee0d5]"><Upload size={16} /> استيراد نسخة<input type="file" accept="application/json,.json" className="hidden" onChange={e => { const file = e.target.files?.[0]; if (file) void importBackup(file); e.currentTarget.value = ''; }} /></label></div><div className="mt-5 rounded-2xl bg-[#e9ddf8] p-4 text-xs font-bold leading-5 text-[#685477]">تتضمن النسخة الموظفات والتقييمات وسجل النشاط والإعدادات، ويمكن نقلها بين نسخ النظام.</div></SettingsCard></div></div>; }
function SettingsCard({ title, description, icon, children }: { title: string; description: string; icon: ReactNode; children: ReactNode }) { return <section className="rounded-[26px] bg-[#fffaf3] p-5 clay sm:p-6"><div className="mb-5 flex items-center gap-3"><div className="rounded-2xl bg-[#e8dcf8] p-3 text-[#73578b]">{icon}</div><div><h3 className="font-display text-xl font-extrabold">{title}</h3><p className="text-xs text-[#a18a90]">{description}</p></div></div>{children}</section>; }
function SettingSlider({ label, value, onChange, suffix }: { label: string; value: number; onChange: (n: number) => void; suffix: string }) { return <label className="mb-5 block last:mb-0"><div className="mb-2 flex justify-between text-sm font-bold"><span>{label}</span><span className="font-display text-lg text-[#896b9c]">{value}{suffix}</span></div><input type="range" min="0" max={suffix === '/ 5' ? 5 : 100} step={suffix === '/ 5' ? .1 : 1} value={value} onChange={e => onChange(Number(e.target.value))} className="w-full accent-[#b294df]" data-testid={`input-setting-${label}`} /></label>; }
function Empty({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) { return <div className="rounded-[26px] bg-[#fffaf3] p-12 text-center clay"><div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-[35%] bg-[#e8dcf8] text-[#775c91]"><Sparkles size={25} /></div><h3 className="font-display text-xl font-extrabold">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-[#9d848a]">{detail}</p>{action && <div className="mt-5">{action}</div>}</div>; }
function Login() { const [, setLocation] = useLocation(); return <div dir="rtl" className="relative flex min-h-[100dvh] items-center justify-center overflow-hidden bg-[#f7efdf] p-4"><div className="absolute -right-20 -top-20 h-72 w-72 rounded-full bg-[#f4b6ca]/60" /><div className="absolute -bottom-24 -left-10 h-80 w-80 rounded-full bg-[#c9b1ef]/60" /><div className="relative grid w-full max-w-5xl overflow-hidden rounded-[36px] bg-[#fffaf3] clay lg:grid-cols-[1fr_1.05fr]"><div className="relative hidden min-h-[620px] overflow-hidden bg-[#c9ead8] p-10 lg:block"><div className="absolute -right-14 bottom-5 h-72 w-72 rounded-full bg-[#edb0c8]/65" /><div className="absolute left-10 top-10 h-28 w-28 rounded-full bg-[#f8e2bd]/75" /><div className="relative flex h-full flex-col justify-between"><div className="flex items-center gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-[32%] bg-[#fff0e6] text-[#855d75]"><ShieldCheck size={23} /></div><span className="font-display text-xl font-extrabold text-[#416650]">نظام إدارة الجودة</span></div><div><div className="mb-5 flex h-24 w-24 rotate-[-8deg] items-center justify-center rounded-[35%] bg-[#fff0e6]/80 text-[#a55d78] clay-sm"><HeartShape /></div><h1 className="font-display text-5xl font-extrabold leading-[1.05] text-[#3c604b]">كل تقييم<br /><span className="text-[#9b5975]">يصنع فرقاً.</span></h1><p className="mt-5 max-w-xs text-sm leading-7 text-[#567664]">مساحتك الهادئة لفهم أداء الفريق، والاحتفاء بالعمل الذي لا يراه الجميع.</p></div><div className="rounded-[24px] bg-[#fff5ec]/70 p-5 text-sm font-bold text-[#587064]">“الجودة ليست رقماً فقط، إنها شعور يصل للعميل.”</div></div></div><div className="p-7 sm:p-12 lg:p-16"><div className="mb-12 flex items-center gap-3 lg:hidden"><div className="flex h-11 w-11 items-center justify-center rounded-[32%] bg-[#d7c0f2] text-[#5d4773]"><ShieldCheck size={23} /></div><span className="font-display text-xl font-extrabold">نظام إدارة الجودة</span></div><div className="mb-9"><Badge tone="lavender">دخول آمن للنظام</Badge><h2 className="mt-5 font-display text-4xl font-extrabold text-[#4f3946]">مرحباً بعودتكِ</h2><p className="mt-2 text-sm leading-6 text-[#9b8087]">ادخلي إلى نظام إدارة الجودة، أو ابدئي العرض التجريبي مباشرة.</p></div><form onSubmit={e => { e.preventDefault(); setLocation('/'); }} className="space-y-4"><Field label="البريد الإلكتروني" value="quality@quality-system.demo" onChange={() => {}} /><Field label="كلمة المرور" value="••••••••" onChange={() => {}} type="password" /><div className="flex items-center justify-between pt-1 text-xs font-bold text-[#9d7b87]"><label className="flex items-center gap-2"><input type="checkbox" defaultChecked className="accent-[#b294df]" /> تذكريني</label><button type="button" className="text-[#a36581]">نسيتِ كلمة المرور؟</button></div><Button type="submit" className="mt-4 w-full py-3.5 text-base">الدخول إلى النظام <ChevronLeft size={18} /></Button></form><div className="my-7 flex items-center gap-3 text-xs text-[#b29a9f]"><span className="h-px flex-1 bg-[#eaded5]" /> أو <span className="h-px flex-1 bg-[#eaded5]" /></div><Button variant="soft" className="w-full" onClick={() => setLocation('/')}><Sparkles size={16} /> تجربة الوضع التجريبي مباشرة</Button><p className="mt-7 text-center text-[11px] leading-5 text-[#b09a9e]">بيانات العرض محفوظة على هذا الجهاز فقط<br />ولا تحتاج إلى Firebase أو حساب حقيقي.</p></div></div></div>; }
function HeartShape() { return <div className="relative h-12 w-12 rotate-[-45deg] rounded-tl-[20px] bg-[#e89ab5] after:absolute after:bottom-0 after:left-0 after:h-12 after:w-12 after:rounded-full after:bg-[#e89ab5] before:absolute before:right-0 before:top-0 before:h-12 before:w-12 before:rounded-full before:bg-[#e89ab5]" />; }

function AppState({ children }: { children: ReactNode }) {
  const [employees, setEmployees] = useState(employeesSeed); const [evaluations, setEvaluations] = useState(evalsSeed); const [activities, setActivities] = useState(activitySeed); const [config, setConfig] = useState(defaultConfig);
  const store: Store = { employees, evaluations, activities, config, addEvaluation: e => setEvaluations(v => [{ ...e, id: `v${Date.now()}` }, ...v]), updateEvaluation: e => setEvaluations(v => v.map(x => x.id === e.id ? e : x)), deleteEvaluation: id => setEvaluations(v => v.filter(x => x.id !== id)), addEmployee: e => setEmployees(v => [...v, { ...e, id: `e${Date.now()}` }]), updateEmployee: e => setEmployees(v => v.map(x => x.id === e.id ? e : x)), toggleEmployee: id => setEmployees(v => v.map(x => x.id === id ? { ...x, active: !x.active } : x)), deleteEmployee: id => setEmployees(v => v.filter(x => x.id !== id)), addActivity: (action, detail) => setActivities(v => [{ id: `a${Date.now()}`, timestamp: 'الآن', user: 'أنتِ', action, detail }, ...v]), setConfig, restoreData: data => { if (data.employees) setEmployees(data.employees); if (data.evaluations) setEvaluations(data.evaluations); if (data.activities) setActivities(data.activities); if (data.config) setConfig(data.config); } };
  return <StoreContext.Provider value={store}>{children}</StoreContext.Provider>;
}
function Router() { const [location] = useLocation(); const isLogin = location === '/login'; return isLogin ? <Switch><Route path="/login" component={Login} /></Switch> : <Shell><Switch><Route path="/" component={Dashboard} /><Route path="/evaluations" component={Evaluations} /><Route path="/bulk-entry" component={BulkEntry} /><Route path="/employees" component={Employees} /><Route path="/employee-report" component={EmployeeReport} /><Route path="/monthly-report" component={MonthlyReport} /><Route path="/activity" component={Activity} /><Route path="/settings" component={SettingsPage} /><Route component={() => <Empty title="الصفحة غير موجودة" detail="يبدو أن هذا الرابط أخذ استراحة قصيرة." action={<Link href="/" className="inline-flex rounded-2xl bg-[#c5a7ee] px-4 py-2.5 font-bold" data-testid="link-back-home">العودة للرئيسية</Link>} />} /></Switch></Shell>; }
const queryClient = new QueryClient();
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><AppState><ErrorBoundary resetKey={location.pathname}><Router /></ErrorBoundary></AppState></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;